@namespace sv_4cd3a04ad4434368afddeddb0997b859.Components.Pages.Apply

<section class="step-content">
    <h2>Personal Information</h2>

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" value="@Model.FullName"
               @onchange="e => UpdateModel(Model with { FullName = (string?)e.Value ?? "" })" />
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" value="@Model.Email"
               @onchange="e => UpdateModel(Model with { Email = (string?)e.Value ?? "" })" />
        @if (!string.IsNullOrEmpty(EmailError))
        {
            <span class="validation-error">@EmailError</span>
        }
    </div>

    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" value="@Model.Phone"
               @onchange="e => UpdateModel(Model with { Phone = (string?)e.Value ?? "" })" />
    </div>

    <div class="form-group">
        <label>Address *</label>
        <textarea rows="2" value="@Model.Address"
                  @onchange="e => UpdateModel(Model with { Address = (string?)e.Value ?? "" })"></textarea>
    </div>

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-actions">
        <button type="button" class="btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @(IsValidating ? "Validating..." : "Next")
        </button>
    </div>
</section>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<PersonalInfoModel> OnModelChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public Func<string, Task<bool>> ValidateEmail { get; set; } = default!;

    private string? ValidationError;
    private string? EmailError;
    private bool IsValidating;

    private void UpdateModel(PersonalInfoModel updated)
    {
        EmailError = null;
        OnModelChanged.InvokeAsync(updated);
    }

    private async Task HandleNext()
    {
        ValidationError = null;
        EmailError = null;

        if (string.IsNullOrWhiteSpace(Model.FullName) ||
            string.IsNullOrWhiteSpace(Model.Email) ||
            string.IsNullOrWhiteSpace(Model.Phone) ||
            string.IsNullOrWhiteSpace(Model.Address))
        {
            ValidationError = "All fields are required.";
            return;
        }

        IsValidating = true;
        try
        {
            var isValid = await ValidateEmail(Model.Email);
            if (!isValid)
            {
                EmailError = "Please enter a valid email address.";
                return;
            }
            await OnNext.InvokeAsync();
        }
        finally
        {
            IsValidating = false;
        }
    }
}

@namespace sv_4cd3a04ad4434368afddeddb0997b859.Components.Pages.Apply

<section class="step-content">
    <h2>Work History</h2>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="@Entries[index]"
                       Index="index"
                       CanRemove="@(Entries.Count > 1)"
                       OnEntryChanged="e => UpdateEntry(index, e)"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button type="button" class="btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-actions">
        <button type="button" class="btn-secondary" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</section>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<List<WorkEntryModel>> OnEntriesChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? ValidationError;

    private void UpdateEntry(int index, WorkEntryModel updated)
    {
        var list = new List<WorkEntryModel>(Entries);
        list[index] = updated;
        OnEntriesChanged.InvokeAsync(list);
    }

    private void RemoveEntry(int index)
    {
        var list = new List<WorkEntryModel>(Entries);
        list.RemoveAt(index);
        OnEntriesChanged.InvokeAsync(list);
    }

    private void AddEntry()
    {
        var list = new List<WorkEntryModel>(Entries)
        {
            new()
        };
        OnEntriesChanged.InvokeAsync(list);
    }

    private void HandleNext()
    {
        ValidationError = null;
        var first = Entries[0];
        if (string.IsNullOrWhiteSpace(first.Company) || string.IsNullOrWhiteSpace(first.Title))
        {
            ValidationError = "At least the first position must have a company and title.";
            return;
        }
        OnNext.InvokeAsync();
    }
}

@namespace sv_4cd3a04ad4434368afddeddb0997b859.Components.Pages.Apply

<section class="step-content">
    <h2>References</h2>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <ReferenceForm Entry="@Entries[index]"
                       Index="index"
                       CanRemove="@(Entries.Count > 1)"
                       OnEntryChanged="e => UpdateEntry(index, e)"
                       OnRemove="() => RemoveEntry(index)" />
    }

    @if (Entries.Count < 3)
    {
        <button type="button" class="btn-secondary" @onclick="AddEntry">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-actions">
        <button type="button" class="btn-secondary" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</section>

@code {
    [Parameter, EditorRequired] public List<ReferenceModel> Entries { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<List<ReferenceModel>> OnEntriesChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? ValidationError;

    private void UpdateEntry(int index, ReferenceModel updated)
    {
        var list = new List<ReferenceModel>(Entries);
        list[index] = updated;
        OnEntriesChanged.InvokeAsync(list);
    }

    private void RemoveEntry(int index)
    {
        var list = new List<ReferenceModel>(Entries);
        list.RemoveAt(index);
        OnEntriesChanged.InvokeAsync(list);
    }

    private void AddEntry()
    {
        if (Entries.Count < 3)
        {
            var list = new List<ReferenceModel>(Entries) { new() };
            OnEntriesChanged.InvokeAsync(list);
        }
    }

    private void HandleNext()
    {
        ValidationError = null;
        var first = Entries[0];
        if (string.IsNullOrWhiteSpace(first.Name) || string.IsNullOrWhiteSpace(first.Email))
        {
            ValidationError = "At least the first reference must have a name and email.";
            return;
        }
        OnNext.InvokeAsync();
    }
}

@namespace sv_4cd3a04ad4434368afddeddb0997b859.Components.Pages.Apply

<section class="step-content">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <textarea rows="12" maxlength="2000" value="@CoverLetter"
                  @oninput="HandleInput"></textarea>
        <div class="char-count">@CoverLetter.Length / 2000 characters</div>
    </div>

    <div class="step-actions">
        <button type="button" class="btn-secondary" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="OnNext">Next</button>
    </div>
</section>

@code {
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<string> OnCoverLetterChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private void HandleInput(ChangeEventArgs e)
    {
        var value = (string?)e.Value ?? "";
        if (value.Length <= 2000)
        {
            OnCoverLetterChanged.InvokeAsync(value);
        }
    }
}

@namespace sv_4cd3a04ad4434368afddeddb0997b859.Components.Pages.Apply

<section class="step-content">
    <h2>Review & Submit</h2>

    <div class="review-section">
        <h3>Personal Information <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button></h3>
        <dl>
            <dt>Full Name</dt><dd>@Personal.FullName</dd>
            <dt>Email</dt><dd>@Personal.Email</dd>
            <dt>Phone</dt><dd>@Personal.Phone</dd>
            <dt>Address</dt><dd>@Personal.Address</dd>
        </dl>
    </div>

    <div class="review-section">
        <h3>Work History <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button></h3>
        @foreach (var entry in WorkEntries)
        {
            <div class="review-entry">
                <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                <br />
                <span>@entry.StartDate.ToString("MMM yyyy") &ndash; @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")</span>
                @if (!string.IsNullOrWhiteSpace(entry.Description))
                {
                    <p>@entry.Description</p>
                }
            </div>
        }
    </div>

    <div class="review-section">
        <h3>References <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button></h3>
        @foreach (var r in References)
        {
            <div class="review-entry">
                <strong>@r.Name</strong> (@r.Relationship)
                <br />@r.Email | @r.Phone
            </div>
        }
    </div>

    <div class="review-section">
        <h3>Cover Letter <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button></h3>
        <p class="cover-letter-preview">@CoverLetter</p>
    </div>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="validation-error">@ErrorMessage</div>
    }

    <div class="step-actions">
        <button type="button" class="btn-secondary" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleSubmit" disabled="@IsSubmitting">
            @(IsSubmitting ? "Submitting..." : "Submit Application")
        </button>
    </div>
</section>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Personal { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryModel> WorkEntries { get; set; } = default!;
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<int> OnEditStep { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter, EditorRequired] public Func<Task> OnSubmit { get; set; } = default!;

    private bool IsSubmitting;
    private string? ErrorMessage;

    private async Task HandleSubmit()
    {
        IsSubmitting = true;
        ErrorMessage = null;
        try
        {
            await OnSubmit();
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            IsSubmitting = false;
        }
    }
}

