@namespace sv_4cd3a04ad4434368afddeddb0997b859.Components.Pages.Apply

<section class="step-content">
    <h2>Review & Submit</h2>

    <div class="review-section">
        <h3>Personal Information <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button></h3>
        <dl>
            <dt>Full Name</dt><dd>@Personal.FullName</dd>
            <dt>Email</dt><dd>@Personal.Email</dd>
            <dt>Phone</dt><dd>@Personal.Phone</dd>
            <dt>Address</dt><dd>@Personal.Address</dd>
        </dl>
    </div>

    <div class="review-section">
        <h3>Work History <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button></h3>
        @foreach (var entry in WorkEntries)
        {
            <div class="review-entry">
                <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                <br />
                <span>@entry.StartDate.ToString("MMM yyyy") &ndash; @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")</span>
                @if (!string.IsNullOrWhiteSpace(entry.Description))
                {
                    <p>@entry.Description</p>
                }
            </div>
        }
    </div>

    <div class="review-section">
        <h3>References <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button></h3>
        @foreach (var r in References)
        {
            <div class="review-entry">
                <strong>@r.Name</strong> (@r.Relationship)
                <br />@r.Email | @r.Phone
            </div>
        }
    </div>

    <div class="review-section">
        <h3>Cover Letter <button class="btn-link" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button></h3>
        <p class="cover-letter-preview">@CoverLetter</p>
    </div>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="validation-error">@ErrorMessage</div>
    }

    <div class="step-actions">
        <button type="button" class="btn-secondary" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleSubmit" disabled="@IsSubmitting">
            @(IsSubmitting ? "Submitting..." : "Submit Application")
        </button>
    </div>
</section>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Personal { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryModel> WorkEntries { get; set; } = default!;
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<int> OnEditStep { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter, EditorRequired] public Func<Task> OnSubmit { get; set; } = default!;

    private bool IsSubmitting;
    private string? ErrorMessage;

    private async Task HandleSubmit()
    {
        IsSubmitting = true;
        ErrorMessage = null;
        try
        {
            await OnSubmit();
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            IsSubmitting = false;
        }
    }
}

