arguments.file_text:
@page "/apply"
@namespace sv_4cd3a04ad4434368afddeddb0997b859.Components.Pages.Apply
@using sv_4cd3a04ad4434368afddeddb0997b859.Models
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h1>Job Application</h1>

    @if (IsSubmitted)
    {
        <div class="confirmation">
            <h2>&#10003; Application Submitted!</h2>
            <p>Your application has been received. Your confirmation number is:</p>
            <strong class="application-id">@ApplicationId</strong>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="@CurrentStep"
                       CompletedSteps="@CompletedSteps"
                       OnStepClicked="GoToStep" />

        @switch (CurrentStep)
        {
            case 0:
                <PersonalInfoStep Model="@PersonalInfo"
                                  OnModelChanged="m => PersonalInfo = m"
                                  OnNext="() => AdvanceStep()"
                                  ValidateEmail="ValidateEmailAsync" />
                break;
            case 1:
                <WorkHistoryStep Entries="@WorkEntries"
                                 OnEntriesChanged="e => WorkEntries = e"
                                 OnNext="() => AdvanceStep()"
                                 OnBack="() => GoToStep(CurrentStep - 1)" />
                break;
            case 2:
                <ReferencesStep Entries="@References"
                                OnEntriesChanged="e => References = e"
                                OnNext="() => AdvanceStep()"
                                OnBack="() => GoToStep(CurrentStep - 1)" />
                break;
            case 3:
                <CoverLetterStep CoverLetter="@CoverLetter"
                                 OnCoverLetterChanged="s => CoverLetter = s"
                                 OnNext="() => AdvanceStep()"
                                 OnBack="() => GoToStep(CurrentStep - 1)" />
                break;
            case 4:
                <ReviewStep Personal="@PersonalInfo"
                            WorkEntries="@WorkEntries"
                            References="@References"
                            CoverLetter="@CoverLetter"
                            OnEditStep="GoToStep"
                            OnBack="() => GoToStep(CurrentStep - 1)"
                            OnSubmit="SubmitAsync" />
                break;
        }
    }
</div>

@code {
    [Inject] private IApplicationService ApplicationService { get; set; } = default!;

    private int CurrentStep;
    private HashSet<int> CompletedSteps = new();
    private bool IsSubmitted;
    private int ApplicationId;

    private PersonalInfoModel PersonalInfo = new();
    private List<WorkEntryModel> WorkEntries = new() { new() };
    private List<ReferenceModel> References = new() { new(), new() };
    private string CoverLetter = "";

    private void AdvanceStep()
    {
        CompletedSteps.Add(CurrentStep);
        CurrentStep++;
    }

    private void GoToStep(int step)
    {
        if (step <= CurrentStep || CompletedSteps.Contains(step))
        {
            CurrentStep = step;
        }
    }

    private async Task<bool> ValidateEmailAsync(string email)
    {
        return await ApplicationService.ValidateEmailAsync(email);
    }

    private async Task SubmitAsync()
    {
        var application = new JobApplication(
            new PersonalInfo(PersonalInfo.FullName, PersonalInfo.Email, PersonalInfo.Phone, PersonalInfo.Address),
            new WorkHistory(WorkEntries.Select(e => new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList()),
            References.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
            CoverLetter
        );

        ApplicationId = await ApplicationService.SubmitApplicationAsync(application);
        IsSubmitted = true;
    }
}

.apply-page {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    margin-bottom: 2rem;
    padding: 1rem 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.25rem;
}

.step-icon {
    width: 2rem;
    height: 2rem;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.875rem;
    border: 2px solid #ccc;
    background: white;
    color: #999;
}

.step-current .step-icon {
    border-color: #2563eb;
    background: #2563eb;
    color: white;
}

.step-completed .step-icon {
    border-color: #16a34a;
    background: #16a34a;
    color: white;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    max-width: 5rem;
    color: #666;
}

.step-current .step-label {
    color: #2563eb;
    font-weight: 600;
}

.step-completed .step-label {
    color: #16a34a;
}

.step-future .step-label {
    color: #999;
}

.step-button {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.25rem;
    background: none;
    border: none;
    cursor: pointer;
    padding: 0;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #ddd;
    margin: 0 0.5rem;
    align-self: center;
    margin-bottom: 1rem;
}

.step-connector-completed {
    background: #16a34a;
}

/* Form Elements */
.step-content {
    background: #f9fafb;
    border-radius: 8px;
    padding: 2rem;
    border: 1px solid #e5e7eb;
}

.step-content h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #111827;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.25rem;
    color: #374151;
}

.form-group input,
.form-group textarea {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #d1d5db;
    border-radius: 4px;
    font-size: 1rem;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #2563eb;
    box-shadow: 0 0 0 2px rgba(37, 99, 235, 0.1);
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.5rem;
    font-weight: normal !important;
    margin-top: 0.5rem;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Buttons */
.step-actions {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    gap: 1rem;
}

.btn-primary {
    background: #2563eb;
    color: white;
    border: none;
    padding: 0.75rem 1.5rem;
    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
    font-weight: 500;
}

.btn-primary:hover:not(:disabled) {
    background: #1d4ed8;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-secondary {
    background: white;
    color: #374151;
    border: 1px solid #d1d5db;
    padding: 0.75rem 1.5rem;
    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
}

.btn-secondary:hover {
    background: #f3f4f6;
}

.btn-remove {
    background: #fee2e2;
    color: #dc2626;
    border: 1px solid #fca5a5;
    padding: 0.5rem 1rem;
    border-radius: 4px;
    font-size: 0.875rem;
    cursor: pointer;
    margin-top: 0.5rem;
}

.btn-remove:hover {
    background: #fecaca;
}

.btn-link {
    background: none;
    border: none;
    color: #2563eb;
    cursor: pointer;
    font-size: 0.875rem;
    text-decoration: underline;
    padding: 0;
    margin-left: 0.5rem;
}

/* Fieldsets */
fieldset {
    border: 1px solid #e5e7eb;
    border-radius: 6px;
    padding: 1.5rem;
    margin-bottom: 1rem;
    background: white;
}

fieldset legend {
    font-weight: 600;
    padding: 0 0.5rem;
    color: #374151;
}

/* Validation */
.validation-error {
    color: #dc2626;
    font-size: 0.875rem;
    margin-top: 0.5rem;
}

/* Character Count */
.char-count {
    text-align: right;
    font-size: 0.875rem;
    color: #6b7280;
    margin-top: 0.25rem;
}

/* Review Step */
.review-section {
    margin-bottom: 1.5rem;
    padding-bottom: 1.5rem;
    border-bottom: 1px solid #e5e7eb;
}

.review-section:last-of-type {
    border-bottom: none;
}

.review-section h3 {
    margin: 0 0 0.75rem;
    display: flex;
    align-items: center;
}

.review-section dl {
    display: grid;
    grid-template-columns: 8rem 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #6b7280;
}

.review-section dd {
    margin: 0;
}

.review-entry {
    margin-bottom: 0.75rem;
    padding: 0.5rem;
    background: white;
    border-radius: 4px;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: white;
    padding: 1rem;
    border-radius: 4px;
    border: 1px solid #e5e7eb;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 3rem 2rem;
    background: #f0fdf4;
    border: 1px solid #bbf7d0;
    border-radius: 8px;
}

.confirmation h2 {
    color: #16a34a;
    font-size: 1.5rem;
}

.application-id {
    display: inline-block;
    font-size: 2rem;
    color: #111827;
    background: white;
    padding: 0.5rem 1.5rem;
    border-radius: 4px;
    border: 1px solid #e5e7eb;
    margin-top: 0.5rem;
}

